struct J{double v,d1,d2,d3,d4;};
inline J add(J a,J b){return {a.v+b.v,a.d1+b.d1,a.d2+b.d2,a.d3+b.d3,a.d4+b.d4};}
inline J scale(J a,double s){return {s*a.v,s*a.d1,s*a.d2,s*a.d3,s*a.d4};}
inline J logadd(J a,J b){
  if(!isfinite(a.v)) return b; if(!isfinite(b.v)) return a;
  double m=max(a.v,b.v), ea=exp(a.v-m), eb=exp(b.v-m), z=ea+eb, wa=ea/z, wb=eb/z;
  auto A2=[](J x){return x.d2+x.d1*x.d1;};
  auto A3=[](J x){return x.d3+3*x.d1*x.d2+x.d1*x.d1*x.d1;};
  auto A4=[](J x){return x.d4+4*x.d1*x.d3+3*x.d2*x.d2+6*x.d1*x.d1*x.d2+pow(x.d1,4);};
  double M1=wa*a.d1+wb*b.d1;
  double M2=wa*A2(a)+wb*A2(b);
  double M3=wa*A3(a)+wb*A3(b);
  double M4=wa*A4(a)+wb*A4(b);
  double L2=M2-M1*M1;
  double L3=M3-3*M2*M1+2*M1*M1*M1;
  double L4=M4-4*M3*M1-3*M2*M2+12*M2*M1*M1-6*pow(M1,4);
  return {m+log(z),M1,L2,L3,L4};
}
inline uint64_t pack(const State&s){uint64_t x=0;for(int i=0;i<12;i++)x|=((uint64_t)s[i])<<(3*i);return x;} inline State unpack(uint64_t x){State s{};for(int i=0;i<12;i++)s[i]=(x>>(3*i))&7;return s;}
inline uint64_t tpack(const State&s,int a,int eps){State t{};for(int i=0;i<12;i++){int j=(eps*i+a)%12;if(j<0)j+=12;t[j]=s[i];}return pack(t);} unordered_map<uint64_t,uint64_t> CC; unordered_map<uint64_t,double> NC; inline uint64_t canon(const State&s){uint64_t raw=pack(s);auto it=CC.find(raw);if(it!=CC.end())return it->second;uint64_t b=raw;for(int eps:{1,-1})for(int a=0;a<12;a++)b=min(b,tpack(s,a,eps));CC.emplace(raw,b);return b;}
inline int tot(uint64_t p){int z=0;for(int i=0;i<12;i++)z+=(p>>(3*i))&7;return z;}
inline double normp(uint64_t p){auto it=NC.find(p);if(it!=NC.end())return it->second;int a[12];for(int i=0;i<12;i++)a[i]=(p>>(3*i))&7;double z=0;for(int i=0;i<12;i++)for(int j=0;j<12;j++)z+=a[i]*G[i][j]*a[j];NC.emplace(p,z);return z;}
inline double dlt(uint64_t a,uint64_t b,uint64_t c){int m=tot(c);return (2*normp(a)+2*normp(b)-normp(c))/m;}
struct Key{uint64_t s;uint8_t e;bool operator==(Key const&o)const{return s==o.s&&e==o.e;}};struct KH{size_t operator()(Key const&k)const{return (k.s*11400714819323198485ull)^k.e;}};
unordered_map<Key,J,KH> MEM; double beta0; uint64_t splitcount=0;
J solve(uint64_t pc,int e);
void recspl(uint64_t pc,const State&c,int i,int rem,State&a,int e,J &L){if(i==12){if(rem)return;State b{};for(int k=0;k<12;k++)b[k]=c[k]-a[k];uint64_t pa=pack(a),pb=pack(b);if(pa>pb)return;splitcount++;uint64_t ca=canon(a),cb=canon(b);double d=dlt(pa,pb,pc),q=ldexp(1.0,e);J energy={-beta0*q*d,-q*d,0.0,0.0,0.0}, term;if(pa!=pb) term=add(energy,add(solve(ca,e+1),solve(cb,e+1)));else {J x=scale(solve(ca,e+1),2.0), y=solve(ca,e+2);term=add(energy,logadd(x,y));term.v-=log(2.0);}L=logadd(L,term);return;}int tail=0;for(int k=i+1;k<12;k++)tail+=c[k];for(int v=max(0,rem-tail);v<=min<int>(c[i],rem);v++){a[i]=v;recspl(pc,c,i+1,rem-v,a,e,L);}a[i]=0;}
J solve(uint64_t pc,int e){Key K{pc,(uint8_t)e};auto it=MEM.find(K);if(it!=MEM.end())return it->second;if(tot(pc)==1)return MEM.emplace(K,J{0,0,0,0,0}).first->second;State c=unpack(pc),a{};J L{-INFINITY,0,0,0,0};recspl(pc,c,0,tot(pc)/2,a,e,L);MEM.emplace(K,L);return L;}
struct Obs{double C,dC,skew,binder;};
Obs evalmask(int mask,double b){beta0=b;MEM.clear();splitcount=0;State r{};r.fill(1);for(int i=0;i<12;i++)if(mask&(1<<i))r[i]=2;J z=solve(canon(r),0);double C=b*b*z.d2,dC=2*b*z.d2+b*b*z.d3,sk=-z.d3/pow(z.d2,1.5),bu=-z.d4/(3*z.d2*z.d2);return {C,dC,sk,bu};}
